exploreUrl:
@js:
sort=[];
push=(title,url,type1,type2)=>sort.push({
		title: title,
		url: url,
		style: {
				layout_flexGrow: type1,
				layout_flexBasisPercent: type2
			}
	});
push("全部🌊分类",null,1,1)
	arList=["🌊全部漫画🌊","🌊3D漫画🌊","🌊韩漫🌊","🌊日漫🌊","🌊真人漫画🌊","🌊耽美BL漫画🌊"]
	mrList=["全部","完结","连载"]
	nrList=["最热门","最新更新","最新上架"]
	arList.map((tag,index)=>{
		push(tag, `/manga/library?type=${index}&complete=1&page={{page}}&orderby=1`, 1, 1);
		mrList.map((teg,uri)=>{
			push(teg,`/manga/library?type=${index}&complete=${uri+1}&page={{page}}&orderby=1`, 1,0.25);
});
			nrList.map((tsg,ure)=>{
			mrList.map((teg,uri)=>{
				push(tsg,`/manga/library?type=${index}&complete=${uri+1}&page={{page}}&orderby=${ure+1}`, 1,0.25);
});
		});
		});

//java.log(JSON.stringify(sort))
JSON.stringify(sort)

